/* generated root CSS: 00-tokens/tokens.css */
/* ============================================================
   lab-ui · canonical tokens · light theme
   ----------------------------------------------------------------
   Source-of-truth design tokens for the ServiceWand block catalog.
   Extracted from sw-styles.css (servicewand.com light theme) +
   additive --font-mono from v5 (JetBrains Mono).
   ============================================================ */

:root {
  /* ─── Palette (raw brand colors) ─────────────────────────── */
  --color-black:        #1B1D25;
  --color-white:        #FFFFFF;
  --color-gray:         #BEC5D3;
  --color-gray-second:  #5C6474;
  --color-gray-blue:    #97A2B8;
  --color-gray-light:   #D9D9D9;

  --color-cyan:         #6BEAF9;
  --color-blue:         #4F95FF;
  --color-red:          #FF6C56;
  --color-green:        #7DDE8E;
  --color-orange:       #FFA72C;
  --color-magenta:      #EF5CFF;

  --color-black-bg:           #17171B;
  --color-gray-bg:            #F9F9F9;
  --color-light-card-bg:      #F7F7F74D;
  --color-header-footer-bg:   rgba(77, 79, 104, 0.20);

  --color-dark-card-bg:       linear-gradient(180deg, #20232D 0%, #2C2D3C 100%);
  --color-light-gray-stroke:  linear-gradient(179.96deg, #E0E8F4 0.03%, #D1D6DD 102.68%);
  --color-dark-gray-stroke:   linear-gradient(180deg, #454F6B 0%, #2F2F40 100%);

  /* ─── Brand CTA rainbow gradient (locked: v5 direction + stops) */
  --gradient-cta-ring:
    linear-gradient(250deg,
      rgba(107, 237, 249, 0)   4.98%,
      #6bedf9                 37.35%,
      #ffa72c                 72.51%,
      rgba(239, 92, 255, 0)   96.41%);

  /* ─── Typography ─────────────────────────────────────────── */
  --font-family:        "Vela Sans", sans-serif;
  --font-mono:          "JetBrains Mono", ui-monospace, "SF Mono", Menlo, monospace;

  /* Type scale */
  --type-h1-size:       clamp(2.25rem, 5.2vw, 5rem);
  --type-h1-weight:     500;
  --type-h1-tracking:   -0.025em;
  --type-h1-leading:    1.04;

  --type-h2-size:       clamp(1.75rem, 3.4vw, 3.125rem);
  --type-h2-weight:     600;
  --type-h2-tracking:   -0.022em;
  --type-h2-leading:    1.15;

  --type-h3-size:       clamp(1.125rem, 1.6vw, 1.5625rem);
  --type-h3-weight:     600;
  --type-h3-tracking:   -0.015em;
  --type-h3-leading:    1.25;

  --type-h4-size:       1.125rem;
  --type-h4-weight:     600;
  --type-h4-tracking:   -0.01em;

  --type-lead-size:     clamp(1rem, 1.25vw, 1.25rem);
  --type-lead-weight:   400;
  --type-lead-leading:  1.5;

  --type-body-size:     1rem;
  --type-body-leading:  1.55;

  --type-eyebrow-size:  0.8125rem;
  --type-eyebrow-tracking: 0.12em;

  /* ─── Layout ─────────────────────────────────────────────── */
  --container-width:     105rem;
  --container-padding-x: 1.875rem;
  --header-height:       4.6875rem;

  /* Backdrop blur — header chrome */
  --backdrop-blur-header:    1.25rem;
  --backdrop-blur-table:     2.5rem;
  --backdrop-blur-ecosystem: 5rem;

  /* ─── Radii ──────────────────────────────────────────────── */
  --radius-pill:    6.25rem;
  --radius-card:    1.25rem;
  --radius-card-sm: 0.9375rem;

  /* ─── Motion ─────────────────────────────────────────────── */
  --transition-duration: 0.4s;

  /* ─── Semantic tokens · LIGHT theme (canonical default) ──── */
  --color-bg:           var(--color-white);
  --color-bg-invert:    var(--color-black-bg);
  --color-text:         var(--color-gray-second);
  --color-heading:      var(--color-black);
  --color-link:         var(--color-black);
  --color-link-hover:   var(--color-gray-second);

  --header-bg:          var(--color-light-card-bg);
  --card-bg:            var(--color-gray-bg);
  --card-border:        var(--color-light-gray-stroke);
  --locale-selector-bg: var(--color-gray-bg);

  --button-primary-bg:        transparent;
  --button-primary-color:     var(--color-black);

  --button-secondary-bg:      transparent;
  --button-secondary-color:   var(--color-black);
  --button-secondary-border:  var(--color-black);

  --button-burger-button-bg:  var(--color-black);

  --input-bg:           var(--color-light-card-bg);

  /* ─── CTA · vertical accent system ─────────────────────────
     --cta-accent is the page-wide interactive accent. It tints:
       · hover-rise glow (effect.hover-rise)
       · primary CTA outer hover glow (box-shadow)
       · secondary CTA always-on halo
       · italic accent word in hero titles
     --cta-secondary-fill is the filled background of secondary CTAs.
     Per-vertical overrides go through [data-vertical="..."] below.   */
  --cta-accent:          var(--color-cyan);
  --cta-accent-soft:     rgba(107, 234, 249, 0.30);
  --cta-secondary-fill:  linear-gradient(90deg, #56422D 0%, #494938 100%);
  --cta-secondary-color: var(--color-white);
  --cta-secondary-border:rgba(255, 255, 255, 0.18);
}

/* ─── Vertical accent overlays ────────────────────────────────
   Set on <body data-vertical="..."> or any wrapper. Cascades into
   every CTA, hover-rise effect, and accent text inside the scope. */

[data-vertical="snow-removal"] {
  /* Default cyan — kept explicit so authors see the slot exists. */
  --cta-accent:          #6BEAF9;
  --cta-accent-soft:     rgba(107, 234, 249, 0.30);
  --cta-secondary-fill:  linear-gradient(90deg, #56422D 0%, #494938 100%);
}

[data-vertical="lawn-care"] {
  --cta-accent:          #7DDE8E;
  --cta-accent-soft:     rgba(125, 222, 142, 0.28);
  --cta-secondary-fill:  linear-gradient(90deg, #1E4D2F 0%, #2D5A3D 100%);
}

[data-vertical="hvac"] {
  --cta-accent:          #FFA72C;
  --cta-accent-soft:     rgba(255, 167, 44, 0.28);
  --cta-secondary-fill:  linear-gradient(90deg, #5A3D1E 0%, #6B4A28 100%);
}

[data-vertical="pest-control"] {
  --cta-accent:          #FF6C56;
  --cta-accent-soft:     rgba(255, 108, 86, 0.28);
  --cta-secondary-fill:  linear-gradient(90deg, #5A2D28 0%, #6B3A35 100%);
}

[data-vertical="tree-care"] {
  --cta-accent:          #7DDE8E;
  --cta-accent-soft:     rgba(125, 222, 142, 0.28);
  --cta-secondary-fill:  linear-gradient(90deg, #234728 0%, #345937 100%);
}

[data-vertical="plumbing"] {
  --cta-accent:          #4F95FF;
  --cta-accent-soft:     rgba(79, 149, 255, 0.28);
  --cta-secondary-fill:  linear-gradient(90deg, #1E3850 0%, #2C4A66 100%);
}

[data-vertical="electrical"] {
  --cta-accent:          #FFA72C;
  --cta-accent-soft:     rgba(255, 167, 44, 0.28);
  --cta-secondary-fill:  linear-gradient(90deg, #4D3D1E 0%, #5C4A28 100%);
}

[data-vertical="cleaning"] {
  --cta-accent:          #EF5CFF;
  --cta-accent-soft:     rgba(239, 92, 255, 0.28);
  --cta-secondary-fill:  linear-gradient(90deg, #3A2858 0%, #4B3370 100%);
}


/* generated root CSS: 01-header/header.sw-default/block.css */
/* lab-ui block · header.sw-default
   Depends: 00-tokens/tokens.css + 03-cta/cta.btn-primary-ring/block.css
   + 04-language/language.sw-locale-dropdown/block.css. Light theme.

   Multi-level nav model:
     .nav-item[data-kind="link"]      — plain anchor (no panel)
     .nav-item[data-kind="dropdown"]  — trigger + .nav-panel--list  (single-column)
     .nav-item[data-kind="mega"]      — trigger + .nav-panel--mega  (multi-column)

   Desktop panels open on :hover + :focus-within and on [data-open="true"]
   (the latter is for click/tap toggling via block.js). Below 1024px,
   the burger reveals a full-width menu and nested panel links are shown
   inline instead of as accordions. */

.header--default {
  position: sticky;
  top: 0;
  z-index: 40;
  background: rgba(255, 255, 255, 0.78);
  backdrop-filter: blur(var(--backdrop-blur-header, 1.25rem));
  -webkit-backdrop-filter: blur(var(--backdrop-blur-header, 1.25rem));
  border-bottom-left-radius: 2rem;
  border-bottom-right-radius: 2rem;
  box-shadow: 0 18px 46px -34px rgba(27, 29, 37, 0.42);
  transition: background-color var(--transition-duration) ease,
              box-shadow var(--transition-duration) ease;
}

.header--default .container {
  max-width: calc(var(--container-width) + var(--container-padding-x) * 2);
  margin-inline: auto;
  padding-inline: var(--container-padding-x);
}

.header--default .header-inner {
  position: relative;
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 26px;
  min-height: 4.375rem;
  font-family: var(--font-family);
}

.header--default .header-logo {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: var(--color-heading);
  text-decoration: none;
}
.header--default .header-logo svg {
  width: 20px;
  height: 20px;
}
.header--default .header-logo-text {
  font-size: 1.125rem;
  font-weight: 600;
  letter-spacing: -0.018em;
}

/* ─── Nav (unified) ─── */
.header-nav {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  justify-self: center;
}

.nav-item { position: relative; }

.nav-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 12px;
  border-radius: 999px;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--color-heading);
  text-decoration: none;
  transition: background 0.2s ease, color 0.2s ease;
  background: transparent;
  border: 0;
  cursor: pointer;
  font-family: inherit;
  line-height: 1;
}
.nav-link:hover,
.nav-item:hover > .nav-link,
.nav-item[data-open="true"] > .nav-link {
  background: rgba(27, 29, 37, 0.045);
}

.nav-chev { transition: transform 0.2s ease; }
.nav-item:hover .nav-chev,
.nav-item:focus-within .nav-chev,
.nav-item[data-open="true"] .nav-chev { transform: rotate(180deg); }

/* ─── Panels (shared base) ─── */
.nav-panel {
  position: absolute;
  top: calc(100% + 8px);
  background: rgba(255, 255, 255, 0.94);
  border: 1px solid rgba(27, 29, 37, 0.08);
  border-radius: 18px;
  box-shadow: 0 24px 60px -26px rgba(27, 29, 37, 0.34);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  opacity: 0;
  pointer-events: none;
  transform: translateY(-4px);
  transition: opacity 0.18s ease, transform 0.18s ease;
  z-index: 50;
}

/* Invisible hover-bridge that spans the 8 px gap between the trigger
   and the panel. Without it, mouse moving from trigger down into the
   panel leaves nav-item's bounding box mid-gap, :hover drops, panel
   closes before the mouse arrives. The bridge is a child of .nav-panel
   (so it inherits the parent's pointer-events:auto when the panel is
   open) and extends UP from the panel's top edge by 10 px so it covers
   the visual gap. Stays full panel width so diagonal mouse paths still
   land in it. */
.nav-panel::before {
  content: "";
  position: absolute;
  top: -10px;
  left: 0;
  right: 0;
  height: 10px;
  /* background: rgba(255,0,0,0.15);  ← uncomment to debug */
}

.nav-item:hover > .nav-panel,
.nav-item:focus-within > .nav-panel,
.nav-item[data-open="true"] > .nav-panel {
  opacity: 1;
  pointer-events: auto;
  transform: translateY(0);
}

/* ─── List panel (dropdown) ─── */
.nav-panel--list {
  left: 50%;
  transform: translateX(-50%) translateY(-4px);
  min-width: 220px;
  padding: 8px;
  display: flex;
  flex-direction: column;
  gap: 2px;
  list-style: none;
  margin: 0;
}
.nav-item:hover > .nav-panel--list,
.nav-item:focus-within > .nav-panel--list,
.nav-item[data-open="true"] > .nav-panel--list {
  transform: translateX(-50%) translateY(0);
}
.nav-list-link {
  display: block;
  padding: 10px 14px;
  border-radius: 12px;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--color-heading);
  text-decoration: none;
  transition: background 0.15s ease;
}
.nav-list-link:hover { background: rgba(27, 29, 37, 0.045); }

/* ─── Mega panel ─── */
.nav-panel--mega {
  left: 50%;
  transform: translateX(-50%) translateY(-4px);
  width: max-content;
  max-width: min(680px, 92vw);
  padding: 14px;
  display: grid;
  grid-template-columns: repeat(2, minmax(176px, 1fr));
  gap: 12px 16px;
}
.nav-item:hover > .nav-panel--mega,
.nav-item:focus-within > .nav-panel--mega,
.nav-item[data-open="true"] > .nav-panel--mega {
  transform: translateX(-50%) translateY(0);
}
.nav-mega-col { display: flex; flex-direction: column; gap: 4px; min-width: 0; }
.nav-mega-title {
  margin: 0 0 5px;
  font-family: var(--font-mono);
  font-size: 0.625rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--color-gray-blue);
  font-weight: 500;
}
.nav-mega-link {
  display: block;
  padding: 8px 10px;
  border-radius: 12px;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--color-heading);
  text-decoration: none;
  transition: background 0.15s ease;
}
.nav-mega-link:hover { background: rgba(27, 29, 37, 0.045); }

/* Hide empty mega columns / links via block.js (sets [hidden]) */
.nav-panel [hidden] { display: none !important; }

/* ─── Optional Breadcrumb Chip ───
   Breadcrumb is owned by header.sw-default. It hangs from the sticky
   header's bottom edge inside the same page/header host. */
.bc-chip {
  position: absolute;
  top: var(--header-height, 4.6875rem);
  left: var(--container-padding-x);
  z-index: 30;
  display: inline-flex;
  align-items: center;
  gap: 14px;
  height: 38px;
  padding: 0 18px;
  border-radius: 0 0 18px 18px;
  font-family: var(--font-family);
  font-size: 13px;
  color: var(--color-text);
  background: linear-gradient(
    188.96deg,
    rgba(255, 255, 255, 0.85) 15.85%,
    rgba(224, 224, 224, 0.17) 92.84%
  );
  backdrop-filter: blur(3.125rem);
  -webkit-backdrop-filter: blur(3.125rem);
  border: 1px solid rgba(0, 0, 0, 0.04);
  border-top: 0;
  box-shadow: 0 6px 16px -12px rgba(0, 0, 0, 0.18);
  white-space: nowrap;
  min-width: 0;
  max-width: calc(100vw - var(--container-padding-x) * 2);
}

.bc-chip .bc-link {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  color: var(--color-text);
  text-decoration: none;
  transition: color 0.15s ease;
}

.bc-chip .bc-link:hover { color: var(--color-heading); }

.bc-chip .bc-root {
  font-weight: 500;
  color: var(--color-heading);
}

.bc-chip .bc-sep {
  color: var(--color-gray-blue);
  font-family: var(--font-mono);
  font-size: 11px;
}

.bc-chip .bc-current {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  color: var(--color-heading);
  font-weight: 500;
}

.bc-chip [data-mid][hidden],
.bc-chip [data-sep-for][hidden] {
  display: none !important;
}

.header-host.is-open .bc-chip,
body.is-open .bc-chip {
  display: none;
  opacity: 0;
  pointer-events: none;
}

/* ─── Actions ─── */
.header-actions {
  display: inline-flex;
  align-items: center;
  gap: 10px;
}
.header-cta { min-width: auto; height: 2.625rem; padding: 0 1.2rem; font-size: 0.9375rem; }

/* ─── Burger ─── */
.burger {
  display: none;
  flex-direction: column;
  gap: 4px;
  width: 2.625rem;
  height: 2.625rem;
  align-items: center;
  justify-content: center;
  border-radius: 0;
  background: transparent;
  border: 0;
  cursor: pointer;
  color: var(--color-heading);
  padding: 0;
}
.burger span { width: 18px; height: 1.5px; background: var(--color-heading); border-radius: 1px; }

/* ─── Responsive ─── */

/* 1280→1100 px : tighten gaps + nav-link padding so the row still
   fits when the viewport gets closer to tablet width. Mega panel
   reflows to 1-col at the same threshold so it doesn't overflow
   the (now narrower) container. */
@media (max-width: 1280px) {
  .header--default .header-inner { gap: 18px; }
  .header-nav { gap: 0; }
  .nav-link { padding: 8px 10px; font-size: 0.8125rem; }
}
@media (max-width: 1100px) {
  .nav-panel--mega { grid-template-columns: 1fr; max-width: 280px; }
  .header-cta { min-width: 0; padding: 0 14px; font-size: 0.875rem; }
}

/* ≤1024 px : tablet portrait + everything below. The nav collapses
   into the burger sheet, while CTA + locale stay compact in the header.
   The burger toggle is wired by block.js (.header-host.is-open). */
@media (max-width: 1024px) {
  .header--default {
    border-bottom-left-radius: 1.75rem;
    border-bottom-right-radius: 1.75rem;
  }
  .header--default .container {
    padding-inline: 1.5rem;
  }
  .header--default .header-inner {
    grid-template-columns: minmax(0, auto) auto;
    justify-content: space-between;
    gap: 12px;
    min-height: 3.75rem;
  }
  .header--default .header-logo {
    min-width: 0;
  }
  .header--default .header-logo-text {
    font-size: 1.0625rem;
  }
  .header-nav {
    position: absolute;
    top: 100%;
    left: -1.5rem;
    right: -1.5rem;
    width: auto;
    display: flex;
    flex-direction: column;
    align-items: stretch;
    justify-self: stretch;
    gap: 18px;
    max-height: calc(100vh - 3.75rem);
    padding: 1.25rem clamp(1.5rem, 6vw, 3rem) 1.5rem;
    overflow-y: auto;
    opacity: 0;
    pointer-events: none;
    visibility: hidden;
    transform: translateY(-8px);
    clip-path: inset(0 0 100% 0 round 0 0 1.75rem 1.75rem);
    background: #fff;
    border: 0;
    border-bottom-left-radius: 1.75rem;
    border-bottom-right-radius: 1.75rem;
    box-shadow: 0 24px 60px -34px rgba(27, 29, 37, 0.32);
    backdrop-filter: blur(18px);
    -webkit-backdrop-filter: blur(18px);
    z-index: 80;
    scrollbar-width: none;
    -ms-overflow-style: none;
    transition:
      opacity 0.28s ease,
      transform 0.28s ease,
      clip-path 0.28s ease,
      visibility 0s linear 0.28s;
  }
  .header-nav::-webkit-scrollbar {
    display: none;
    width: 0;
    height: 0;
  }
  body.is-open .header--default .header-nav,
  .header-host.is-open .header--default .header-nav {
    opacity: 1;
    pointer-events: auto;
    visibility: visible;
    transform: translateY(0);
    clip-path: inset(0 0 0 0 round 0 0 1.75rem 1.75rem);
    transition-delay: 0s;
  }
  body.is-open,
  .header-host.is-open {
    overflow-x: clip;
  }
  .nav-item { width: 100%; }
  .nav-link {
    width: 100%;
    justify-content: flex-start;
    padding: 0;
    border-radius: 0;
    font-size: 1.0625rem;
    font-weight: 500;
    line-height: 1.25;
    text-align: left;
  }
  .nav-link:hover,
  .nav-item:hover > .nav-link,
  .nav-item[data-open="true"] > .nav-link {
    background: transparent;
  }
  .nav-chev { display: none; }
  .nav-panel,
  .nav-panel--list,
  .nav-panel--mega {
    position: static;
    width: 100%;
    max-width: none;
    min-width: 0;
    margin: 10px 0 0 18px;
    box-shadow: none;
    border: 0;
    border-radius: 0;
    transform: none;
    opacity: 1;
    pointer-events: auto;
    background: transparent;
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
  }
  .nav-panel::before { display: none; }
  .nav-panel--list { display: flex; }
  .nav-panel--mega { display: grid; }
  .nav-item:hover > .nav-panel,
  .nav-item:focus-within > .nav-panel,
  .nav-item[data-open="true"] > .nav-panel,
  .nav-item:hover > .nav-panel--list,
  .nav-item:focus-within > .nav-panel--list,
  .nav-item[data-open="true"] > .nav-panel--list,
  .nav-item:hover > .nav-panel--mega,
  .nav-item:focus-within > .nav-panel--mega,
  .nav-item[data-open="true"] > .nav-panel--mega {
    transform: none;
  }
  .nav-panel--mega {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 12px 22px;
    padding: 0;
  }
  .nav-panel--list {
    gap: 7px;
    padding: 0;
  }
  .nav-mega-col { gap: 7px; }
  .nav-mega-title {
    margin-bottom: 2px;
    font-size: 0.625rem;
  }
  .nav-mega-link,
  .nav-list-link {
    padding: 0;
    border-radius: 0;
    font-size: 0.8125rem;
    line-height: 1.35;
    color: var(--color-text);
  }
  .nav-mega-link:hover,
  .nav-list-link:hover { background: transparent; color: var(--color-heading); }
  .header-actions {
    gap: 8px;
    justify-self: end;
  }
  .header-cta {
    order: 1;
    display: inline-flex;
    height: 2.25rem;
    min-width: 0;
    padding: 0 0.9rem;
    font-size: 0.8125rem;
    white-space: nowrap;
  }
  .header-cta .btn-star {
    width: 13px;
    height: 13px;
  }
  .header-actions .locale-selector {
    order: 2;
    display: block;
  }
  .header-actions .locale-trigger {
    width: 2.25rem;
    min-width: 0;
    height: 2.25rem;
    justify-content: center;
    padding: 0;
